"use client";

import React, { createContext, useContext, useState, useEffect } from "react";
import { X, Phone } from "lucide-react";
import BookingForm from "./BookingForm";

interface BookingModalOptions {
  direction?: string;
  service?: string;
  doctor?: string;
}

interface BookingModalContextValue {
  openBookingModal: (options?: BookingModalOptions) => void;
  closeBookingModal: () => void;
}

const BookingModalContext = createContext<BookingModalContextValue>({
  openBookingModal: () => {},
  closeBookingModal: () => {},
});

export function useBookingModal() {
  return useContext(BookingModalContext);
}

export function BookingModalTrigger({
  direction,
  service,
  doctor,
  children,
  className = "",
}: {
  direction?: string;
  service?: string;
  doctor?: string;
  children: React.ReactNode;
  className?: string;
}) {
  const { openBookingModal } = useBookingModal();
  return (
    <button
      type="button"
      onClick={() => openBookingModal({ direction, service, doctor })}
      className={className}
    >
      {children}
    </button>
  );
}

export default function BookingModalProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [modalOptions, setModalOptions] = useState<BookingModalOptions>({});

  const openBookingModal = (options: BookingModalOptions = {}) => {
    setModalOptions(options);
    setIsOpen(true);
  };

  const closeBookingModal = () => {
    setIsOpen(false);
  };

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") closeBookingModal();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen]);

  return (
    <BookingModalContext.Provider
      value={{ openBookingModal, closeBookingModal }}
    >
      {children}

      {isOpen && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="booking-modal-title"
          className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 overflow-y-auto bg-[#14221E]/60 backdrop-blur-xs"
          onClick={(e) => {
            if (e.target === e.currentTarget) closeBookingModal();
          }}
        >
          <div className="relative w-full max-w-2xl rounded-2xl border border-[#E6E3DC] bg-[#FAF9F6] p-6 sm:p-8 shadow-2xl my-auto max-h-[92vh] overflow-y-auto">
            <div className="flex items-start justify-between gap-4 pb-5 border-b border-[#E6E3DC]">
              <div>
                <span className="inline-block text-xs font-semibold uppercase tracking-widest text-[#9A754D] mb-1">
                  Стоматологическая клиника «Квалитет» • Москва
                </span>
                <h2
                  id="booking-modal-title"
                  className="font-serif-editorial text-2xl sm:text-3xl font-semibold text-[#14221E]"
                >
                  Запись на приём и консультацию
                </h2>
              </div>
              <button
                type="button"
                onClick={closeBookingModal}
                aria-label="Закрыть окно записи"
                className="flex h-10 w-10 items-center justify-center rounded-full border border-[#E6E3DC] bg-white text-[#525D59] hover:bg-[#F3F1EC] hover:text-[#14221E] transition"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="pt-5">
              <BookingForm
                key={`${modalOptions.direction || ""}-${modalOptions.service || ""}-${modalOptions.doctor || ""}`}
                initialDirection={modalOptions.direction}
                initialService={modalOptions.service}
                initialDoctor={modalOptions.doctor}
              />
            </div>

            <div className="mt-6 pt-4 border-t border-[#E6E3DC] flex flex-wrap items-center justify-between gap-2 text-xs text-[#525D59]">
              <span>Запись по телефону регистратуры:</span>
              <div className="flex flex-wrap items-center gap-3 font-medium text-[#164E43] tabular-nums">
                <a
                  href="tel:+74994813208"
                  className="inline-flex items-center gap-1 hover:underline"
                >
                  <Phone className="h-3.5 w-3.5" />
                  +7 (499) 481-32-08
                </a>
                <a href="tel:+74994819700" className="hover:underline">
                  +7 (499) 481-97-00
                </a>
                <a href="tel:+79660194119" className="hover:underline">
                  +7 (966) 019-41-19
                </a>
              </div>
            </div>
          </div>
        </div>
      )}
    </BookingModalContext.Provider>
  );
}
